def create_llm() -> ChatOpenAI:
    return ChatOpenAI(model="gpt-4.1-mini", temperature=0)


def create_vector_store(documents: list[Document], collection_name: str) -> Chroma:
    embeddings = OpenAIEmbeddings(model="text-embedding-3-small")
    vector_store = Chroma(
        collection_name=collection_name,
        embedding_function=embeddings,
        persist_directory="./chromadb",
    )
    vector_store.add_documents(documents)
    return vector_store


def show_docs(docs: list[Document]) -> None:
    for index, doc in enumerate(docs, start=1):
        print(
            f"{index}. {doc.metadata.get('source', 'unknown')} "
            f"({len(doc.page_content)} chars)"
        )
        print(doc.page_content)
        print()
